-- ============================================================
-- Setup de base de datos: Plana Docente
-- Posgrado Educación UNMSM — pegar completo en el SQL Editor de Supabase
-- y ejecutar UNA sola vez.
--
-- "lineas_investigacion" es un array de texto (text[]) — cada línea de
-- investigación es un elemento, igual que el arreglo que ya tenías en
-- data/planaDocente.js. "orden" controla el orden de aparición en la
-- lista (los números más bajos van primero); se sembró con el mismo
-- orden en que ya estaban en el código.
--
-- El cruce "¿en qué programa dicta este docente?" (data/docentesPorPrograma.js)
-- sigue funcionando igual: se sigue calculando en el navegador cruzando
-- esta tabla con los horarios de data/matricula.js (eso no se movió a
-- base de datos, no hacía falta).
--
-- Se deja sembrada la misma información que ya estaba en el código
-- (data/planaDocente.js, 59 docentes), así el sitio no queda vacío apenas
-- se corre esto.
-- ============================================================

create table plana_docente (
  id uuid primary key default gen_random_uuid(),
  codigo text,
  apellidos text not null,
  nombres text not null,
  grado text,
  categoria text,
  orcid text,
  renacyt text,
  grupo_investigacion text,
  lineas_investigacion text[] not null default '{}',
  biodata text,
  orden integer not null default 0,
  created_at timestamptz default now()
);

alter table plana_docente enable row level security;

create policy "lectura publica plana docente" on plana_docente for select using (true);

create policy "admin escribe plana docente" on plana_docente for all
  using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

-- Bucket público para el CV/biodata que el admin suba directo desde el
-- panel (además de poder simplemente pegar un link externo, como los de
-- Drive que ya se usaban).

create policy "lectura publica de archivos de plana docente" on storage.objects for select
  using (bucket_id = 'plana-docente-archivos');
create policy "admin sube archivos de plana docente" on storage.objects for insert
  with check (bucket_id = 'plana-docente-archivos' and auth.role() = 'authenticated');

